-- ============================================================================
-- PROJECT_FIT — PATCH i18n EXERCICES (FR) — à coller UNE fois dans le SQL Editor
-- Migration 0009 (colonnes FR) + traductions des 52 exercices. Idempotent.
-- L'anglais reste dans les colonnes d'origine ; l'app choisit selon la langue.
-- ============================================================================

begin;

alter table exercises
  add column if not exists name_fr            text,
  add column if not exists description_fr     text,
  add column if not exists instructions_fr    text[],
  add column if not exists common_mistakes_fr text[];

update exercises set name_fr='Développé couché à la barre', description_fr='Poussée horizontale polyarticulaire pour la force et le volume des pectoraux.', instructions_fr=ARRAY['Allongé à plat, prise un peu plus large que les épaules.','Descends la barre au milieu de la poitrine en contrôlant.','Pousse jusqu''à extension complète des bras.']::text[], common_mistakes_fr=ARRAY['Faire rebondir la barre sur la poitrine.','Écarter les coudes à 90 degrés.']::text[] where slug='barbell-bench-press';
update exercises set name_fr='Développé couché haltères', description_fr='Développé aux haltères permettant une plus grande amplitude.', instructions_fr=ARRAY['Allongé à plat, haltères au niveau de la poitrine.','Pousse jusqu''à extension des bras.','Descends en contrôlant.']::text[], common_mistakes_fr=ARRAY['Laisser les haltères partir vers l''avant.','Cambrer excessivement le bas du dos.']::text[] where slug='dumbbell-bench-press';
update exercises set name_fr='Développé incliné à la barre', description_fr='Développé sur banc incliné pour cibler le haut des pectoraux.', instructions_fr=ARRAY['Règle le banc à 30 degrés.','Descends la barre en haut de la poitrine.','Pousse en ligne droite.']::text[], common_mistakes_fr=ARRAY['Incliner le banc trop haut (devient un développé épaules).']::text[] where slug='incline-barbell-press';
update exercises set name_fr='Développé incliné haltères', description_fr='Variante inclinée aux haltères pour le haut des pectoraux.', instructions_fr=ARRAY['Règle le banc à 30 degrés.','Pousse les haltères vers le haut et vers l''intérieur.','Descends au niveau du haut de la poitrine.']::text[], common_mistakes_fr=ARRAY['Cogner les haltères en haut.']::text[] where slug='incline-dumbbell-press';
update exercises set name_fr='Pompes', description_fr='Exercice de poussée fondamental au poids du corps.', instructions_fr=ARRAY['Mains sous les épaules, corps aligné.','Descends jusqu''à ce que la poitrine frôle le sol.','Repousse vers le haut.']::text[], common_mistakes_fr=ARRAY['Laisser les hanches s''affaisser.','Écarter les coudes trop largement.']::text[] where slug='push-up';
update exercises set name_fr='Pompes inclinées', description_fr='Pompes plus faciles avec les mains surélevées.', instructions_fr=ARRAY['Place les mains sur une surface surélevée.','Garde le corps aligné.','Descends puis repousse.']::text[], common_mistakes_fr=ARRAY['Laisser tomber les hanches.']::text[] where slug='incline-push-up';
update exercises set name_fr='Écarté à la poulie', description_fr='Isolation des pectoraux en tension constante.', instructions_fr=ARRAY['Règle les poulies à hauteur de poitrine.','Ramène les poignées en arc de cercle.','Reviens en contrôlant.']::text[], common_mistakes_fr=ARRAY['Transformer le mouvement en développé.','Trop étirer en bas.']::text[] where slug='cable-fly';
update exercises set name_fr='Écarté haltères', description_fr='Isolation des pectoraux aux haltères sur banc.', instructions_fr=ARRAY['Allongé à plat, léger fléchissement des coudes.','Ouvre les bras en arc large.','Ramène les haltères au-dessus de la poitrine.']::text[], common_mistakes_fr=ARRAY['Trop plier les coudes (devient un développé).']::text[] where slug='dumbbell-fly';
update exercises set name_fr='Dips pectoraux', description_fr='Dips au poids du corps, buste penché pour cibler les pectoraux.', instructions_fr=ARRAY['Penche le buste vers l''avant sur les barres parallèles.','Descends jusqu''à sentir l''étirement des pectoraux.','Repousse vers le haut.']::text[], common_mistakes_fr=ARRAY['Descendre trop bas et solliciter les épaules.']::text[] where slug='dips-chest';
update exercises set name_fr='Développé militaire', description_fr='Développé debout à la barre pour la force des épaules.', instructions_fr=ARRAY['Prise à largeur d''épaules, gaine le tronc.','Pousse au-dessus de la tête, recule légèrement la tête puis avance.','Descends jusqu''aux clavicules.']::text[], common_mistakes_fr=ARRAY['Cambrer excessivement le bas du dos.','Pousser la barre vers l''avant.']::text[] where slug='overhead-press';
update exercises set name_fr='Développé épaules haltères', description_fr='Développé au-dessus de la tête aux haltères, assis ou debout.', instructions_fr=ARRAY['Tiens les haltères à hauteur d''épaules.','Pousse au-dessus de la tête.','Descends en contrôlant.']::text[], common_mistakes_fr=ARRAY['Cogner les haltères en haut.']::text[] where slug='dumbbell-shoulder-press';
update exercises set name_fr='Développé Arnold', description_fr='Développé rotatif aux haltères sollicitant les trois faisceaux du deltoïde.', instructions_fr=ARRAY['Commence paumes vers toi.','Tourne et pousse au-dessus de la tête.','Inverse le mouvement en descendant.']::text[], common_mistakes_fr=ARRAY['Tourner trop vite et perdre le contrôle.']::text[] where slug='arnold-press';
update exercises set name_fr='Élévations latérales', description_fr='Isolation des deltoïdes latéraux.', instructions_fr=ARRAY['Léger fléchissement des coudes, lève les bras sur les côtés.','Arrête à hauteur d''épaules.','Redescends lentement.']::text[], common_mistakes_fr=ARRAY['Utiliser l''élan / se balancer.','Hausser les trapèzes.']::text[] where slug='lateral-raise';
update exercises set name_fr='Élévations latérales à la poulie', description_fr='Élévation latérale en tension constante à la poulie.', instructions_fr=ARRAY['Place-toi de côté par rapport à une poulie basse.','Lève le bras à hauteur d''épaules.','Redescends en contrôlant.']::text[], common_mistakes_fr=ARRAY['Se pencher pour tricher.']::text[] where slug='cable-lateral-raise';
update exercises set name_fr='Oiseau (deltoïdes postérieurs)', description_fr='Isolation des deltoïdes postérieurs.', instructions_fr=ARRAY['Buste penché en avant, léger fléchissement des coudes.','Lève les haltères sur les côtés.','Serre les omoplates.']::text[], common_mistakes_fr=ARRAY['Utiliser les trapèzes au lieu des deltoïdes postérieurs.']::text[] where slug='rear-delt-fly';
update exercises set name_fr='Face pull', description_fr='Tirage à la poulie vers le visage pour les deltoïdes postérieurs et la santé du haut du dos.', instructions_fr=ARRAY['Règle la poulie à hauteur de tête avec une corde.','Tire vers le visage, coudes hauts.','Serre puis reviens.']::text[], common_mistakes_fr=ARRAY['Trop de charge et hausser les épaules.']::text[] where slug='face-pull';
update exercises set name_fr='Soulevé de terre', description_fr='Tirage complet en charnière de hanche depuis le sol.', instructions_fr=ARRAY['Barre au-dessus du milieu du pied, charnière et prise.','Gaine, pousse dans le sol en gardant la barre proche.','Verrouille hanches et genoux ensemble.']::text[], common_mistakes_fr=ARRAY['Arrondir le bas du dos.','Laisser la barre s''éloigner du corps.']::text[] where slug='deadlift';
update exercises set name_fr='Soulevé de terre roumain', description_fr='Charnière de hanche mettant l''accent sur ischio-jambiers et fessiers.', instructions_fr=ARRAY['Genoux légèrement fléchis, pousse les hanches vers l''arrière.','Descends la barre le long des jambes.','Ramène les hanches vers l''avant pour te redresser.']::text[], common_mistakes_fr=ARRAY['Trop plier les genoux (devient un squat).']::text[] where slug='romanian-deadlift';
update exercises set name_fr='Tractions (pronation)', description_fr='Tirage vertical au poids du corps ; ajoute de la charge pour progresser.', instructions_fr=ARRAY['Suspends-toi en prise pronation.','Tire jusqu''à passer le menton au-dessus de la barre.','Redescends en contrôlant.']::text[], common_mistakes_fr=ARRAY['Utiliser l''élan (kipping) pour des reps strictes.','Ne pas aller en extension complète.']::text[] where slug='pull-up';
update exercises set name_fr='Tractions supination', description_fr='Traction verticale en supination avec plus de biceps.', instructions_fr=ARRAY['Suspends-toi en prise supination.','Tire le menton au-dessus de la barre.','Redescends complètement.']::text[], common_mistakes_fr=ARRAY['Amplitude partielle.']::text[] where slug='chin-up';
update exercises set name_fr='Tirage vertical (poulie haute)', description_fr='Tirage vertical à la machine, adapté aux débutants.', instructions_fr=ARRAY['Prise plus large que les épaules.','Tire vers le haut de la poitrine.','Reviens en contrôlant.']::text[], common_mistakes_fr=ARRAY['Se pencher trop en arrière.']::text[] where slug='lat-pulldown';
update exercises set name_fr='Rowing barre', description_fr='Tirage horizontal buste penché pour l''épaisseur du dos.', instructions_fr=ARRAY['Charnière à ~45 degrés, dos plat.','Tire la barre vers le bas des côtes.','Descends en contrôlant.']::text[], common_mistakes_fr=ARRAY['Rester trop droit.','Arracher la charge avec le bas du dos.']::text[] where slug='barbell-row';
update exercises set name_fr='Rowing haltère', description_fr='Tirage à un bras en appui.', instructions_fr=ARRAY['Une main et un genou sur le banc.','Tire l''haltère vers la hanche.','Descends complètement.']::text[], common_mistakes_fr=ARRAY['Tourner le buste pour tricher.']::text[] where slug='dumbbell-row';
update exercises set name_fr='Rowing assis à la poulie', description_fr='Tirage horizontal à la poulie pour le milieu du dos.', instructions_fr=ARRAY['Assis bien droit, léger penché vers l''avant au départ.','Tire la poignée vers l''abdomen.','Serre les omoplates.']::text[], common_mistakes_fr=ARRAY['Utiliser le bas du dos pour tirer.']::text[] where slug='seated-cable-row';
update exercises set name_fr='Soulevé de terre trap bar', description_fr='Soulevé de terre accessible avec une barre hexagonale.', instructions_fr=ARRAY['Place-toi à l''intérieur de la barre, saisis les poignées.','Pousse dans le sol.','Verrouille bien droit.']::text[], common_mistakes_fr=ARRAY['Arrondir le dos.']::text[] where slug='trap-bar-deadlift';
update exercises set name_fr='Squat barre (dos)', description_fr='Le roi des mouvements polyarticulaires du bas du corps.', instructions_fr=ARRAY['Barre sur le haut du dos, gaine le tronc.','Assieds-toi vers le bas et l''arrière jusqu''à la profondeur.','Remonte en poussant dans le milieu du pied.']::text[], common_mistakes_fr=ARRAY['Genoux qui rentrent vers l''intérieur.','Talons qui décollent du sol.']::text[] where slug='back-squat';
update exercises set name_fr='Squat avant (front squat)', description_fr='Squat charge à l''avant, accent sur quadriceps et gainage.', instructions_fr=ARRAY['Pose la barre sur les deltoïdes avant.','Garde les coudes hauts, descends en squat.','Remonte en restant droit.']::text[], common_mistakes_fr=ARRAY['Baisser les coudes et s''arrondir vers l''avant.']::text[] where slug='front-squat';
update exercises set name_fr='Goblet squat', description_fr='Squat pour débutants avec un haltère tenu à la poitrine.', instructions_fr=ARRAY['Tiens un haltère à hauteur de poitrine.','Descends entre les genoux.','Remonte.']::text[], common_mistakes_fr=ARRAY['Se pencher trop en avant.']::text[] where slug='goblet-squat';
update exercises set name_fr='Presse à cuisses', description_fr='Mouvement polyarticulaire à la machine pour quadriceps et fessiers.', instructions_fr=ARRAY['Pieds largeur d''épaules sur la plateforme.','Descends jusqu''à ~90 degrés aux genoux.','Pousse sans verrouiller violemment.']::text[], common_mistakes_fr=ARRAY['Laisser le bas du dos s''arrondir hors du dossier.']::text[] where slug='leg-press';
update exercises set name_fr='Fentes marchées', description_fr='Mouvement unilatéral pour quadriceps et fessiers.', instructions_fr=ARRAY['Fais un pas en avant et descends le genou arrière.','Pousse pour enchaîner le pas suivant.','Garde le buste droit.']::text[], common_mistakes_fr=ARRAY['Laisser le genou avant rentrer vers l''intérieur.']::text[] where slug='walking-lunge';
update exercises set name_fr='Squat bulgare', description_fr='Squat sur une jambe, pied arrière surélevé.', instructions_fr=ARRAY['Pied arrière sur un banc.','Descends bien à la verticale.','Remonte en poussant sur le talon avant.']::text[], common_mistakes_fr=ARRAY['Se pencher trop et perdre l''équilibre.']::text[] where slug='bulgarian-split-squat';
update exercises set name_fr='Leg curl (ischio-jambiers)', description_fr='Isolation des ischio-jambiers à la machine.', instructions_fr=ARRAY['Règle le coussin au-dessus des talons.','Fléchis vers les fessiers.','Redescends lentement.']::text[], common_mistakes_fr=ARRAY['Utiliser l''élan.']::text[] where slug='leg-curl';
update exercises set name_fr='Leg extension (quadriceps)', description_fr='Isolation des quadriceps à la machine.', instructions_fr=ARRAY['Coussin sur le bas des tibias.','Tends complètement les genoux.','Redescends en contrôlant.']::text[], common_mistakes_fr=ARRAY['Balancer la charge.']::text[] where slug='leg-extension';
update exercises set name_fr='Hip thrust', description_fr='Extension de hanche axée sur les fessiers.', instructions_fr=ARRAY['Haut du dos sur un banc, barre sur les hanches.','Pousse les hanches jusqu''à l''extension complète.','Redescends en contrôlant.']::text[], common_mistakes_fr=ARRAY['Trop cambrer le bas du dos en haut.']::text[] where slug='hip-thrust';
update exercises set name_fr='Extensions mollets debout', description_fr='Isolation des mollets sur toute l''amplitude.', instructions_fr=ARRAY['Avant des pieds sur une marche.','Monte complètement sur les pointes.','Descends pour un étirement profond.']::text[], common_mistakes_fr=ARRAY['Utiliser une amplitude minuscule.']::text[] where slug='standing-calf-raise';
update exercises set name_fr='Extensions mollets assis', description_fr='Extension mollets genoux fléchis, ciblant le soléaire.', instructions_fr=ARRAY['Coussin sur le bas des cuisses.','Monte complètement les talons.','Descends lentement.']::text[], common_mistakes_fr=ARRAY['Faire rebondir la charge.']::text[] where slug='seated-calf-raise';
update exercises set name_fr='Curl barre', description_fr='Grand classique pour la masse des biceps.', instructions_fr=ARRAY['Prise largeur d''épaules, coudes serrés.','Fléchis jusqu''en haut.','Redescends complètement.']::text[], common_mistakes_fr=ARRAY['Se balancer avec le bas du dos.']::text[] where slug='barbell-curl';
update exercises set name_fr='Curl haltères', description_fr='Curl biceps permettant la supination.', instructions_fr=ARRAY['Fléchis un ou deux haltères.','Tourne l''auriculaire vers le haut en haut du mouvement.','Redescends lentement.']::text[], common_mistakes_fr=ARRAY['Utiliser l''élan.']::text[] where slug='dumbbell-curl';
update exercises set name_fr='Curl marteau', description_fr='Curl en prise neutre pour biceps et brachial.', instructions_fr=ARRAY['Prise neutre, coudes serrés.','Fléchis vers le haut.','Redescends en contrôlant.']::text[], common_mistakes_fr=ARRAY['Balancer la charge.']::text[] where slug='hammer-curl';
update exercises set name_fr='Extensions triceps à la poulie', description_fr='Isolation des triceps à la poulie.', instructions_fr=ARRAY['Coudes collés au corps.','Tends complètement vers le bas.','Reviens en contrôlant.']::text[], common_mistakes_fr=ARRAY['Laisser les coudes partir vers l''avant.']::text[] where slug='tricep-pushdown';
update exercises set name_fr='Extension triceps au-dessus de la tête', description_fr='Extension au-dessus de la tête ciblant la longue portion.', instructions_fr=ARRAY['Tiens la charge au-dessus de la tête.','Descends derrière la tête.','Tends de nouveau vers le haut.']::text[], common_mistakes_fr=ARRAY['Écarter les coudes.']::text[] where slug='overhead-tricep-extension';
update exercises set name_fr='Développé couché prise serrée', description_fr='Variante du développé couché ciblant les triceps.', instructions_fr=ARRAY['Prise à l''intérieur de la largeur d''épaules.','Descends vers le bas de la poitrine, coudes serrés.','Pousse vers le haut.']::text[], common_mistakes_fr=ARRAY['Prise trop serrée qui stresse les poignets.']::text[] where slug='close-grip-bench-press';
update exercises set name_fr='Dips triceps', description_fr='Dips buste droit ciblant les triceps.', instructions_fr=ARRAY['Reste droit sur les barres parallèles.','Descends jusqu''à ~90 degrés.','Repousse vers le haut.']::text[], common_mistakes_fr=ARRAY['Se pencher en avant (bascule vers les pectoraux).']::text[] where slug='dips-triceps';
update exercises set name_fr='Curl poignets', description_fr='Isolation des fléchisseurs de l''avant-bras.', instructions_fr=ARRAY['Avant-bras sur les cuisses, paumes vers le haut.','Fléchis les poignets vers le haut.','Redescends lentement.']::text[], common_mistakes_fr=ARRAY['Utiliser une charge trop lourde.']::text[] where slug='wrist-curl';
update exercises set name_fr='Gainage (planche)', description_fr='Maintien isométrique de stabilité du tronc.', instructions_fr=ARRAY['Avant-bras au sol, corps aligné.','Gaine les abdominaux et les fessiers.','Maintiens la position.']::text[], common_mistakes_fr=ARRAY['Laisser les hanches s''affaisser ou remonter.']::text[] where slug='plank';
update exercises set name_fr='Gainage latéral', description_fr='Maintien latéral pour le tronc et les obliques.', instructions_fr=ARRAY['Sur un avant-bras, corps aligné de côté.','Soulève les hanches.','Maintiens puis change de côté.']::text[], common_mistakes_fr=ARRAY['Laisser les hanches descendre.']::text[] where slug='side-plank';
update exercises set name_fr='Relevé de jambes suspendu', description_fr='Exercice du bas des abdominaux à la barre.', instructions_fr=ARRAY['Suspends-toi à une barre.','Lève les jambes à hauteur de hanches ou plus.','Redescends en contrôlant.']::text[], common_mistakes_fr=ARRAY['Se balancer pour utiliser l''élan.']::text[] where slug='hanging-leg-raise';
update exercises set name_fr='Crunch', description_fr='Flexion abdominale de base.', instructions_fr=ARRAY['Allongé, genoux fléchis.','Décolle les épaules du sol.','Redescends lentement.']::text[], common_mistakes_fr=ARRAY['Tirer sur la nuque.']::text[] where slug='crunch';
update exercises set name_fr='Rotation à la poulie (woodchop)', description_fr='Mouvement de rotation du tronc à la poulie.', instructions_fr=ARRAY['Règle la poulie en haut ou en bas.','Effectue une rotation en travers du corps.','Reviens en contrôlant.']::text[], common_mistakes_fr=ARRAY['Tourner depuis le bas du dos au lieu du tronc.']::text[] where slug='cable-woodchop';
update exercises set name_fr='Russian twist', description_fr='Exercice de rotation des obliques, assis.', instructions_fr=ARRAY['Assis, buste penché en arrière.','Effectue une rotation d''un côté à l''autre.','Garde le tronc gainé.']::text[], common_mistakes_fr=ARRAY['Bouger les bras sans tourner le buste.']::text[] where slug='russian-twist';
update exercises set name_fr='Swing kettlebell', description_fr='Mouvement explosif de charnière de hanche (conditionnement).', instructions_fr=ARRAY['Charnière et lance la kettlebell vers l''arrière.','Claque les hanches pour la propulser à hauteur de poitrine.','Laisse-la redescendre et recommence.']::text[], common_mistakes_fr=ARRAY['Faire un squat au lieu d''une charnière.','Soulever avec les bras.']::text[] where slug='kettlebell-swing';
update exercises set name_fr='Écarté à l''élastique', description_fr='Activation du haut du dos et des deltoïdes postérieurs à l''élastique.', instructions_fr=ARRAY['Tiens un élastique à hauteur d''épaules.','Écarte-le jusqu''à la poitrine.','Reviens en contrôlant.']::text[], common_mistakes_fr=ARRAY['Hausser les épaules.']::text[] where slug='band-pull-apart';

commit;
